    res, cols, d1, d2 = [], set(), set(), set()
    def bt(row, pos):
        if row == n: res.append(pos[:]); return
        for c in range(n):
            if c not in cols and row-c not in d1 and row+c not in d2:
                cols.add(c); d1.add(row-c); d2.add(row+c); pos.append(c+1)
                bt(row+1, pos)
                cols.remove(c); d1.remove(row-c); d2.remove(row+c); pos.pop()
    bt(0, [])
