def find_paths(maze, n):
    res, vis = [], [[False]*n for _ in range(n)]
    dirs = [(1,0,'D'),(0,-1,'L'),(0,1,'R'),(-1,0,'U')]
    def bt(i, j, path):
        if i==n-1 and j==n-1: res.append(path); return
        for di,dj,d in dirs:
            ni,nj = i+di, j+dj
            if 0<=ni<n and 0<=nj<n and maze[ni][nj] and not vis[ni][nj]:
                vis[ni][nj]=True; bt(ni,nj,path+d); vis[ni][nj]=False
    vis[0][0]=True; bt(0,0,''); return res

