def graph_coloring(graph, m, n):
    color = [0]*n
    def safe(v, c):
        return all(not graph[v][i] or color[i]!=c for i in range(n))
    def bt(v):
        if v==n: return True
        for c in range(1,m+1):
            if safe(v,c): color[v]=c; res=bt(v+1); color[v]=0
            if res: return True
        return False
    return color if bt(0) else None

