def find_hamiltonian_cycle(graph, n):
    path = [-1]*n; path[0] = 0
    def safe(v, pos):
        if not graph[path[pos-1]][v]: return False
        return v not in path[:pos]
    def bt(pos):
        if pos==n: return graph[path[-1]][path[0]]
        for v in range(1,n):
            if safe(v,pos): path[pos]=v; r=bt(pos+1); path[pos]=-1
            if r: return True
        return False
    return path if bt(1) else None

