bool dfs(vector<vector<char>>& g, string& w, int i, int j, int k, int m, int n) {
    if(k==w.size()) return true;
    if(i<0||j<0||i>=m||j>=n||g[i][j]!=w[k]) return false;
    char t=g[i][j]; g[i][j]='#';
    bool found=dfs(g,w,i+1,j,k+1,m,n)||dfs(g,w,i-1,j,k+1,m,n)||dfs(g,w,i,j+1,k+1,m,n)||dfs(g,w,i,j-1,k+1,m,n);
    g[i][j]=t; return found;
}

