def knight_tour(n):
    board = [[-1]*n for _ in range(n)]
    dx = [2,1,-1,-2,-2,-1,1,2]
    dy = [1,2,2,1,-1,-2,-2,-1]
    board[0][0] = 0
    def bt(x, y, move):
        if move == n*n: return True
        for k in range(8):
            nx, ny = x+dx[k], y+dy[k]
            if 0<=nx<n and 0<=ny<n and board[nx][ny]==-1:
                board[nx][ny] = move
                if bt(nx, ny, move+1): return True
                board[nx][ny] = -1
        return False
    if bt(0, 0, 1):
        for row in board: print(*[x+1 for x in row])
